// Production dependency license check (CI job `licenses`). Every package `pnpm licenses list --prod`
// reports must have a license in scripts/third-party-notices.mjs ALLOWED (permissive only), because
// Weft's distributed builds are offered under commercial terms as well as the AGPL and cannot carry
// copyleft or source-available third-party code. Bundled devDependencies (the MCP SDK, zod, ajv,
// web-tree-sitter, ...) are checked when the CLI and the VS Code extension are built: their LICENSE
// is generated by buildLicense(), which fails on the same allow-list.
//
//   node scripts/license-check.mjs           exit 1 and list offenders if any
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { licenseAllowed } from "./third-party-notices.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const r = spawnSync("pnpm", ["licenses", "list", "--prod", "--json"], { cwd: root, encoding: "utf8", maxBuffer: 64 << 20 });
if (r.status !== 0) {
  process.stderr.write(r.stderr || "pnpm licenses list failed\n");
  process.exit(2);
}
const byLicense = JSON.parse(r.stdout);
const bad = [];
let count = 0;
for (const [license, pkgs] of Object.entries(byLicense)) {
  for (const p of pkgs) {
    count++;
    if (!licenseAllowed(license)) bad.push(`${p.name}@${(p.versions ?? []).join(",")}: ${license}`);
  }
}
if (bad.length) {
  process.stderr.write(`production dependencies with a license Weft's distributed builds may not carry:\n  ${bad.join("\n  ")}\n`);
  process.exit(1);
}
console.log(`licenses: ${count} production dependencies, all permissive (${Object.keys(byLicense).sort().join(", ")})`);
